export = MyLib;
export as namespace MyLib;

declare namespace MyLib {
    interface Payload<T> {
        value: T;
        onEvent: (value: T) => void;
    }

    type ElementProps<T> = T extends keyof Inner.Table ? Inner.Table[T] : never;

    namespace Inner {
        interface Table {
            button: MyLib.Payload<string>;
            input: MyLib.Payload<number>;
        }
    }
}
